import java.io.*;

public class Main {
    static StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));

    static int nextInt() throws IOException {
        in.nextToken();
        return (int) in.nval;
    }

    public static void main(String[] args) throws IOException {
        long n = nextInt();
        long m = nextInt();

        if (n > m) {
            long t = n;
            n = m;
            m = t;
        }

        long answer;

        if (n == 1) {
            long[] penalty = {0, 1, 2, 3, 2, 1};
            answer = n * m - penalty[(int) (m % 6)];
        } else if (n == 2) {
            if (m == 2) {
                answer = n * m - 4;
            } else if (m == 3 || m == 7) {
                answer = n * m - 2;
            } else {
                answer = n * m;
            }
        } else if (n == 3) {
            answer = n * m - (m & 1L);
        } else {
            answer = n * m - ((n & 1L) & (m & 1L));
        }

        PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));
        out.println(answer);
        out.flush();
    }
}
